import json,html
R=Path('/workspace/scratch/bece6597f7e0');O=R/'output/thesis-literature-2026-10-11'
D=json.loads((O/'papers.json').read_text());P={p['key']:p for p in D['papers']}
keys=['2609.40241','2609.25845','2609.23986','2610.00831','2609.37647','2609.38850']
