 p=P[k];cards.append(f'<article id="{p["id"]}"><p class="tag">{p["id"]} · {roles[k]}</p><h3>{link(k)}</h3><p class="title">{html.escape(p["title"])}</p><p>{html.escape(p["summary"])}</p><p class="limit">{html.escape(p["limitation"])}</p></article>')
